+describe("view_order_reversed", () => {
+    const add = (state, id) =>
+        reduceFlows(
+            state,
+            flowActions.FLOWS_ADD({
+                flow: { ...TFlow(), id },
+                matching_filters: {},
+            }),
+        );
+    const reversed = (state, value: boolean) =>
+        reduceFlows(
+            state,
+            OPTIONS_UPDATE({
+                view_order_reversed: {
+                    value,
+                    default: false,
+                    help: "",
+                    type: "bool",
+                },
+            }),
+        );
+
+    it("is read from OPTIONS_RECEIVE and OPTIONS_UPDATE", () => {
+        const opts = testState.options_meta;
+        let s = reduceFlows(
+            undefined,
+            OPTIONS_RECEIVE({
+                ...opts,
+                view_order_reversed: { ...opts.view_order_reversed, value: true },
+            }),
+        );
+        expect(s.view_order_reversed).toBe(true);
+        s = reversed(s, false);
+        expect(s.view_order_reversed).toBe(false);
+    });
+
+    it("inserts new flows at the front when set", () => {
+        let s = reversed(defaultState, true);
+        for (const id of ["a", "b", "c"]) s = add(s, id);
+        expect(s.view.map((f) => f.id)).toEqual(["c", "b", "a"]);
+        expect(s._viewIndex.get("c")).toBe(0);
+        expect(s._viewIndex.get("a")).toBe(2);
+    });
+
+    it("appends new flows when not set", () => {
+        let s = defaultState;
+        for (const id of ["a", "b", "c"]) s = add(s, id);
+        expect(s.view.map((f) => f.id)).toEqual(["a", "b", "c"]);
+    });
+
+    it("lets an active column sort take precedence", () => {
+        let s = reversed(defaultState, true);
+        s = reduceFlows(
+            s,
+            flowActions.setSort({ column: "path", desc: false }),
+        );
+        for (const id of ["a", "b", "c"]) s = add(s, id);
+        // Equal sort keys: sorted insertion appends, the option is ignored.
+        expect(s.view.map((f) => f.id)).toEqual(["a", "b", "c"]);
+    });
+});
